contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        uint256 reqAmount,
        uint256 reqInterest,
        uint256 reqLoanToCollateral,
        uint256 reqDuration,
        uint256 clearAmount,
        bool repayDirect,
        bool isCallback,
        address approvedTo,
        address newOwner
    ) public payable {
        require(reqLoanToCollateral != 0, "zero loanToCollateral");
        require(reqDuration != 0, "zero duration");

        uint256 reqID = c.requestLoan(reqAmount, reqInterest, reqLoanToCollateral, reqDuration); if (__ESBMC_reverted()) return;

        uint256 loanID = c.clearRequest(reqID, repayDirect, isCallback); if (__ESBMC_reverted()) return;

        c.approveTransfer(approvedTo, loanID); if (__ESBMC_reverted()) return;

        require(approvedTo != address(0), "zero approvedTo");

        c.transferOwnership(loanID); if (__ESBMC_reverted()) return;

        assert(c.approvals(loanID) == address(0));
    }

    receive() external payable {}
}

