    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 reqAmount, uint256 reqInterest, uint256 reqLoanToCollateral, uint256 reqDuration, uint256 clearAmount, bool repayDirect, bool isCallback, address approvedTo, address newOwner) internal {
        vm.assume(reqLoanToCollateral != 0);
        vm.assume(reqDuration != 0);
        uint256 reqID;
        try c.requestLoan(reqAmount, reqInterest, reqLoanToCollateral, reqDuration) returns (uint256 __r) { reqID = __r; } catch { return; }
        uint256 loanID;
        try c.clearRequest(reqID, repayDirect, isCallback) returns (uint256 __r) { loanID = __r; } catch { return; }
        try c.approveTransfer(approvedTo, loanID) {} catch { return; }
        vm.assume(approvedTo != address(0));
        try c.transferOwnership(loanID) {} catch { return; }
        assertTrue(c.approvals(loanID) == address(0));
